<?php if($entity==='leads'&&can('leads.edit')):?><script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('bulkLeadForm'),table=document.querySelector('.data-table'),action=document.getElementById('bulkLeadAction'),submit=document.getElementById('bulkLeadSubmit'),count=document.getElementById('bulkLeadCount');if(!form||!table)return;const head=document.createElement('th');head.className='select-col';head.innerHTML='<input type="checkbox" id="selectAllLeads" aria-label="Select all leads">';table.tHead.rows[0].prepend(head);const boxes=[];[...table.tBodies[0].rows].forEach(row=>{const link=row.querySelector('a[href*="/leads/"]');if(!link||row.querySelector('.empty-state'))return;const match=link.getAttribute('href').match(/\/leads\/(\d+)/);if(!match)return;const cell=document.createElement('td');cell.className='select-col';cell.innerHTML=`<input type="checkbox" name="ids[]" value="${match[1]}" form="bulkLeadForm" data-lead-select>`;row.prepend(cell);boxes.push(cell.firstElementChild)});const all=document.getElementById('selectAllLeads'),sync=()=>{const selected=boxes.filter(box=>box.checked).length;count.textContent=selected;submit.disabled=!selected;all.checked=selected>0&&selected===boxes.length;all.indeterminate=selected>0&&selected<boxes.length};all.addEventListener('change',()=>{boxes.forEach(box=>box.checked=all.checked);sync()});boxes.forEach(box=>box.addEventListener('change',sync));action.addEventListener('change',()=>document.querySelectorAll('[data-bulk-values]').forEach(select=>select.disabled=select.dataset.bulkValues!==action.value));sync()});</script><?php endif;?>
